// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.lmdb.RecordIterator;
import org.junit.jupiter.api.Test;

/**
 * Unit tests for the M-A0 id-authority substrate: {@link PlanValueCatalog}, {@link NativeExecutionContext} and
 * {@link LmdbNativeTermAuthority}. The fake store resolves ids byte-exactly (keyed by lexical spelling, like the LMDB
 * {@code ValueStore}'s disk lookup) while RDF term equality compares language tags case-insensitively — the gap the
 * authority exists to manage.
 */
public class LmdbNativeIdAuthorityTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final long UNKNOWN = LmdbNativeAggregateCompiler.UNKNOWN;

	/** Byte-exact fake store: values keyed by exact spelling, ids resolve back to the stored value. */
	private static final class ExactSpellingSource implements NativeLmdbQuerySource {
		private final Map<String, Long> idsBySpelling = new HashMap<>();
		private final Map<Long, Value> valuesById = new HashMap<>();
		private long nextId = 100;

		long add(Value value) {
			long id = nextId++;
			idsBySpelling.put(spelling(value), id);
			valuesById.put(id, value);
			return id;
		}

		private static String spelling(Value value) {
			if (value instanceof Literal) {
				Literal literal = (Literal) value;
				return literal.getLabel() + "|" + literal.getLanguage().orElse("") + "|" + literal.getDatatype();
			}
			return value.stringValue();
		}

		@Override
		public long idOf(Value value) {
			Long id = idsBySpelling.get(spelling(value));
			return id != null ? id : UNKNOWN;
		}

		@Override
		public Value lazyValue(long id) {
			return valuesById.get(id);
		}

		@Override
		public Object idSpace() {
			return this;
		}

		@Override
		public RecordIterator statements(long subj, long pred, long obj, long context) throws IOException {
			return SyntheticValueSource.EMPTY;
		}

		@Override
		public long count(long subj, long pred, long obj, long context) {
			return 0;
		}

		@Override
		public boolean has(long subj, long pred, long obj, long context) {
			return false;
		}

		@Override
		public double estimate(long subj, long pred, long obj, long context) {
			return 0;
		}

		@Override
		public boolean hasStatementsInSource() {
			return !valuesById.isEmpty();
		}
	}

	private static LmdbNativeTermAuthority authority(ExactSpellingSource store, PlanValueCatalog catalog) {
		return new LmdbNativeTermAuthority(store, catalog, new NativeExecutionContext());
	}

	@Test
	public void lookupOrderIsStoreThenCatalogThenInterner() {
		ExactSpellingSource store = new ExactSpellingSource();
		long storeId = store.add(VF.createLiteral("stored"));
		PlanValueCatalog.Builder builder = new PlanValueCatalog.Builder();
		long planId = builder.internConstant(VF.createLiteral("plan-only"));
		LmdbNativeTermAuthority authority = authority(store, builder.build());

		assertThat(authority.idOfOrIntern(VF.createLiteral("stored"))).isEqualTo(storeId);
		assertThat(authority.idOfOrIntern(VF.createLiteral("plan-only"))).isEqualTo(planId);
		long interned = authority.idOfOrIntern(VF.createLiteral("runtime-only"));
		assertThat(authority.kind(interned)).isEqualTo(NativeIdKind.RUNTIME);
		assertThat(authority.idOfOrIntern(VF.createLiteral("runtime-only")))
				.as("interning is stable within one evaluation")
				.isEqualTo(interned);
		assertThat(authority.kind(storeId)).isEqualTo(NativeIdKind.STORE);
		assertThat(authority.kind(planId)).isEqualTo(NativeIdKind.PLAN);
		assertThat(authority.kind(UNKNOWN)).isEqualTo(NativeIdKind.UNKNOWN);
		assertThat(authority.kind(0L)).isEqualTo(NativeIdKind.NULL_CONTEXT);
	}

	@Test
	public void termEqualityBridgesSpellingsAcrossIdSpaces() {
		ExactSpellingSource store = new ExactSpellingSource();
		long storeId = store.add(VF.createLiteral("hello", "en"));
		LmdbNativeTermAuthority authority = authority(store, PlanValueCatalog.EMPTY);

		// The byte-exact store misses the case-different spelling, so the authority interns it...
		long internedId = authority.idOfOrIntern(VF.createLiteral("hello", "EN"));
		assertThat(authority.kind(internedId)).isEqualTo(NativeIdKind.RUNTIME);
		// ...but term equality and the term hash still recognize the two ids as the same RDF term.
		assertThat(authority.sameRdfTerm(storeId, internedId)).isTrue();
		assertThat(authority.rdfTermHash(storeId)).isEqualTo(authority.rdfTermHash(internedId));
		// And the interned language-tagged literal must never be trusted as proof of store absence.
		assertThat(authority.probeDisposition(internedId)).isEqualTo(TermProbeDisposition.VALUE_GUARDED_PROBE);
		assertThat(authority.probeDisposition(storeId)).isEqualTo(TermProbeDisposition.DIRECT_STORE_ID);
	}

	@Test
	public void distinctLexicalNumericFormsNeverCollapse() {
		ExactSpellingSource store = new ExactSpellingSource();
		LmdbNativeTermAuthority authority = authority(store, PlanValueCatalog.EMPTY);

		long one = authority
				.idOfOrIntern(VF.createLiteral("1", VF.createIRI("http://www.w3.org/2001/XMLSchema#integer")));
		long paddedOne = authority
				.idOfOrIntern(VF.createLiteral("01", VF.createIRI("http://www.w3.org/2001/XMLSchema#integer")));
		assertThat(one).isNotEqualTo(paddedOne);
		assertThat(authority.sameRdfTerm(one, paddedOne))
				.as("SPARQL value equality (1 = 01) must not leak into term identity")
				.isFalse();
		assertThat(authority.probeDisposition(one)).isEqualTo(TermProbeDisposition.DEFINITELY_STORE_ABSENT);
	}

	@Test
	public void importBridgesAuthoritiesAndPassesSentinels() {
		ExactSpellingSource store = new ExactSpellingSource();
		long storeId = store.add(VF.createLiteral("shared"));
		LmdbNativeTermAuthority first = authority(store, PlanValueCatalog.EMPTY);
		LmdbNativeTermAuthority second = authority(store, PlanValueCatalog.EMPTY);

		long firstInterned = first.idOfOrIntern(VF.createLiteral("computed"));
		long imported = second.importId(first, firstInterned);
		assertThat(second.valueOf(imported)).isEqualTo(VF.createLiteral("computed"));
		assertThat(second.importId(first, storeId))
				.as("a store value re-resolves to the same store id in the target authority")
				.isEqualTo(storeId);
		assertThat(second.importId(first, UNKNOWN)).isEqualTo(UNKNOWN);
		assertThat(second.importId(first, 0L)).isEqualTo(0L);
		assertThat(first.importId(first, firstInterned))
				.as("same token: raw copy")
				.isEqualTo(firstInterned);
	}

	@Test
	public void concurrentEvaluationsShareIdNumbersWithoutContamination() {
		ExactSpellingSource store = new ExactSpellingSource();
		LmdbNativeTermAuthority first = authority(store, PlanValueCatalog.EMPTY);
		LmdbNativeTermAuthority second = authority(store, PlanValueCatalog.EMPTY);

		long a = first.idOfOrIntern(VF.createLiteral("value-a"));
		long b = second.idOfOrIntern(VF.createLiteral("value-b"));
		assertThat(a)
				.as("two evaluations mint the same first runtime id number for different values")
				.isEqualTo(b);
		assertThat(first.valueOf(a)).isEqualTo(VF.createLiteral("value-a"));
		assertThat(second.valueOf(b)).isEqualTo(VF.createLiteral("value-b"));
		assertThat(first.token()).isNotEqualTo(second.token());
	}

	@Test
	public void closedContextReleasesStateAndRefusesNewInterning() {
		NativeExecutionContext context = new NativeExecutionContext();
		long id = context.internValue(VF.createLiteral("ephemeral"));
		assertThat(context.contains(id)).isTrue();
		context.close();
		assertThat(context.internedCount()).isZero();
		assertThat(context.contains(id)).isFalse();
		assertThatThrownBy(() -> context.internValue(VF.createLiteral("late")))
				.isInstanceOf(IllegalStateException.class);
	}

	@Test
	public void concurrentInterningOfEqualValuesYieldsOneId() throws Exception {
		NativeExecutionContext context = new NativeExecutionContext();
		Value value = VF.createLiteral("contended");
		ExecutorService pool = Executors.newFixedThreadPool(8);
		try {
			List<Callable<Long>> tasks = new ArrayList<>();
			for (int i = 0; i < 64; i++) {
				tasks.add(() -> context.internValue(value));
			}
			List<Future<Long>> results = pool.invokeAll(tasks);
			long expected = results.get(0).get();
			for (Future<Long> result : results) {
				assertThat(result.get()).isEqualTo(expected);
			}
			assertThat(context.valueOf(expected)).isEqualTo(value);
		} finally {
			pool.shutdownNow();
		}
	}

	@Test
	public void catalogSharesIdsForEqualConstantsAndStaysDense() {
		PlanValueCatalog.Builder builder = new PlanValueCatalog.Builder();
		long first = builder.internConstant(VF.createLiteral("c1"));
		long second = builder.internConstant(VF.createLiteral("c2"));
		long firstAgain = builder.internConstant(VF.createLiteral("c1"));
		assertThat(firstAgain).isEqualTo(first);
		assertThat(second).isEqualTo(first + 1);

		PlanValueCatalog catalog = builder.build();
		assertThat(catalog.size()).isEqualTo(2);
		assertThat(catalog.idOf(VF.createLiteral("c2"))).isEqualTo(second);
		assertThat(catalog.valueOf(first)).isEqualTo(VF.createLiteral("c1"));
		assertThat(catalog.contains(second)).isTrue();
		assertThat(catalog.contains(second + 1)).isFalse();
	}
}
